fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return when {
        seconds >= 1.0 -> {
            val formatted = "%.3f".format(seconds).trimEnd('0').trimEnd('.')
            "${formatted}s"
        }
        seconds >= 0.5 -> {
            val formatted = "%.1f".format(seconds)
            "${formatted}s"
        }
        else -> {
            val denominator = (1.0 / seconds).toLong()
            if (denominator <= 0L) "0s" else "1/${denominator}s"
        }
    }
}

